import { delegate } from 'kerfjs';
import type { SafeHtml } from 'kerfjs';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { StateBanner } from '@kerfjs/ui/state-banner';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/webawesome.css';
import '@awesome.me/webawesome/dist/components/dialog/dialog.js';
import '@awesome.me/webawesome/dist/components/button/button.js';
import './command-palette.css';

// Catalog review: there is no CommandPalette export or command-palette recipe.
// Select chooses values; MenuItem describes navigation; TokenSearchField is a
// structured editor. None supplies command-search semantics. This app composition
// reuses the modal, heading and feedback primitives and adds ordinary search and
// command buttons with a small keyboard adapter.
export interface Command { id: string; label: string; group: string; keywords?: string; disabled?: boolean; run(): void | Promise<void> }
interface HistoryStore { load(): string[]; save(ids: string[]): void }
interface DialogElement extends HTMLElement { open: boolean }
export function mountCommandPalette(root: HTMLElement, paint: (content: SafeHtml) => void, id: string, commands: Command[], history: HistoryStore) {
  let recent = history.load().filter((key, index, all) => all.indexOf(key) === index && commands.some(command => command.id === key)).slice(0, 8);
  let query = '';
  let open = false;
  let running = false;
  let error = '';
  let disposed = false;
  let trigger: HTMLElement | null = null;
  let visible: Command[] = [];
  const getDialog = () => root.querySelector<DialogElement>('wa-dialog')!;
  const getSearch = () => root.querySelector<HTMLInputElement>('[data-command-search]')!;
  function groups(): [string, Command[]][] {
    const matching = commands.filter(command => (command.label + ' ' + (command.keywords ?? '')).toLowerCase().includes(query.trim().toLowerCase()));
    const result: [string, Command[]][] = [];
    const recentCommands = query.trim() ? [] : recent.map(key => matching.find(command => command.id === key)).filter((item): item is Command => !!item);
    if (recentCommands.length) result.push(['Recent commands', recentCommands]);
    for (const command of matching) {
      if (recentCommands.includes(command)) continue;
      let group = result.find(([name]) => name === command.group);
      if (!group) { group = [command.group, []]; result.push(group); }
      group[1].push(command);
    }
    return result;
  }
  function render() {
    const grouped = groups();
    visible = grouped.flatMap(([, items]) => items).filter(command => !command.disabled);
    paint(<div class="palette-host kui-layout">
      <button class="palette-button" type="button" data-action="palette-show">Commands</button>
      <wa-dialog class="palette" without-header label="Commands" aria-labelledby={id + '-title'} aria-describedby={id + '-summary'} open={open}>
        <DialogHeader title="Commands" titleId={id + '-title'} summary="Search commands. Use Tab or Up and Down to browse, Enter to run, and Escape to close." summaryId={id + '-summary'} actions={<wa-button appearance="plain" data-action="palette-close">Close</wa-button>} />
        <div class="kui-dialog-body kui-section-stack">
          <label class="palette-search-label" for={id + '-query'}>Search commands<input id={id + '-query'} data-command-search type="search" value={query} autocomplete="off" disabled={running} /></label>
          <p role="status" aria-live="polite">{running ? 'Running command…' : visible.length + ' available commands'}</p>
          {error && <StateBanner tone="danger" urgency="alert" title="Command could not complete" detail={error} />}
          {grouped.length ? grouped.map(([name, items], index) => <section aria-labelledby={id + '-group-' + index}>
            <h3 id={id + '-group-' + index}>{name}</h3>
            <ul class="palette-results">{items.map(command => <li><button class="palette-button palette-command" type="button" data-action="palette-run" data-command-id={command.id} disabled={command.disabled || running}>{command.label}{command.disabled ? ' — unavailable' : ''}</button></li>)}</ul>
          </section>) : <EmptyState title="No matching commands" detail="Try a shorter search or clear the search field." action={<wa-button data-action="palette-clear">Clear search</wa-button>} />}
        </div>
      </wa-dialog>
    </div>);
  }
  function focusCommand(index: number) {
    const command = visible[index];
    if (!command) return;
    root.querySelector<HTMLElement>('[data-command-id="' + CSS.escape(command.id) + '"]')?.focus();
  }
  async function run(commandId: string | undefined) {
    const command = commands.find(item => item.id === commandId);
    if (!command || command.disabled || running) return;
    running = true; error = ''; render();
    try {
      await command.run();
      if (disposed) return;
      recent = [command.id, ...recent.filter(key => key !== command.id)].slice(0, 8);
      history.save(recent);
      getDialog().open = false;
    } catch {
      if (!disposed) error = 'Your command was not completed. You can try again.';
    } finally {
      if (!disposed) { running = false; render(); if (open && error) getSearch().focus(); }
    }
  }
  const offActions = delegate(root, 'click', '[data-action]', (_event, element) => {
    switch (element.dataset.action) {
      case 'palette-show': trigger = element; trigger.focus(); query = ''; error = ''; open = true; render(); getDialog().open = true; break;
      case 'palette-close': getDialog().open = false; break;
      case 'palette-clear': query = ''; render(); getSearch().value = ''; getSearch().focus(); break;
      case 'palette-run': void run(element.dataset.commandId); break;
    }
  });
  const offInput = delegate(root, 'input', '[data-command-search]', (_event, element) => {
    query = (element as HTMLInputElement).value; render();
  });
  const offKeys = delegate(root, 'keydown', 'wa-dialog', event => {
    const key = event as KeyboardEvent;
    if (key.isComposing || running || key.altKey || key.ctrlKey || key.metaKey) return;
    const target = key.target as HTMLElement;
    const inSearch = target.matches('[data-command-search]');
    const button = target.closest<HTMLElement>('[data-command-id]');
    if (!inSearch && !button) return;
    const index = visible.findIndex(command => command.id === button?.dataset.commandId);
    if (key.key === 'ArrowDown') { key.preventDefault(); focusCommand(inSearch ? 0 : (index + 1) % visible.length); }
    if (key.key === 'ArrowUp') { key.preventDefault(); if (!inSearch && index === 0) getSearch().focus(); else focusCommand(inSearch ? visible.length - 1 : index - 1); }
    if (!inSearch && key.key === 'Home') { key.preventDefault(); focusCommand(0); }
    if (!inSearch && key.key === 'End') { key.preventDefault(); focusCommand(visible.length - 1); }
    if (inSearch && key.key === 'Enter') { key.preventDefault(); void run(visible[0]?.id); }
    // Native command buttons own Enter/Space. Web Awesome owns Escape and Tab containment.
  });
  const afterShow = (event: Event) => { if (event.target === getDialog()) getSearch().focus(); };
  const afterHide = (event: Event) => { if (event.target === getDialog()) { open = false; if (trigger?.isConnected) trigger.focus(); } };
  root.addEventListener('wa-after-show', afterShow);
  root.addEventListener('wa-after-hide', afterHide);
  render();
  return () => { disposed = true; offActions(); offInput(); offKeys(); root.removeEventListener('wa-after-show', afterShow); root.removeEventListener('wa-after-hide', afterHide); };
}

