.palette { --spacing: 0; --width: min(38rem, calc(100vw - 2 * var(--kui-layout-dialog-inset))); }
.palette p, .palette h3 { margin: 0; }
.palette h3 { font-size: var(--kui-font-s); }
.palette-search-label { display: grid; gap: var(--kui-layout-control-gap); }
.palette input, .palette-button { font: inherit; min-height: 2.5rem; box-sizing: border-box; padding: var(--kui-space-xs) var(--kui-space-s); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); color: var(--kui-color-text); background: var(--kui-color-surface); }
.palette input { width: 100%; min-width: 0; }
.palette-results { list-style: none; margin: var(--kui-space-xs) 0 0; padding: 0; display: grid; gap: var(--kui-layout-control-gap); }
.palette-command { width: 100%; text-align: start; overflow-wrap: anywhere; }
.palette-button:focus-visible, .palette input:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
.palette-button:hover:enabled { background: var(--kui-color-neutral-fill-quiet); }
.palette-button:disabled { cursor: not-allowed; }
/* Modal body owns scrolling; result groups do not create nested scroll areas. */
